namespace Codalus.Workbench.Ai.Ide;

/// <summary>M60's tools for agents: Git: status, diffs, history and blame, staging, commits, stashes, branches and conflicts. Never a push or a forced operation.</summary>
/// <remarks>
/// D52: reading tools never change the repository; the actions stage, commit (the user's identity, no trailers), stash,
/// check out a branch and resolve conflicts, through the same <c>GitService</c> as Git Changes, so the window follows.
/// Nothing pushes, pulls, fetches, resets, rebases, amends or deletes a branch. Files excluded from AI are left out of
/// every answer and can't be changed by these tools.
/// </remarks>
public static class IdeGitTools
{
    /// <summary>The group's tools, in the order agents see them.</summary>
    public static IReadOnlyList<IdeToolDefinition> Tools { get; } =
    [
        IdeTools.Read("git_status", "The git status of the workspace's repository in Codalus IDE (as Git Changes shows it): the branch, its upstream and how far ahead or behind, an operation in progress (merge, rebase…), and the staged, unstaged, untracked and conflicted files.", "{}"),
        IdeTools.Read("git_diff", "A unified diff: the working tree against the index (default), the staged changes (staged: true), or a commit against its parent (commit). Of one file (path) or every changed file.", """{"path":{"type":"string","description":"A file, relative to the workspace root; empty for every changed file."},"staged":{"type":"boolean","description":"The staged changes (the index against HEAD) instead of the unstaged ones."},"commit":{"type":"string","description":"A commit (hash, branch or tag): its changes against its first parent, with its message."}}"""),
        IdeTools.Read("git_log", "The history, newest first: each commit's short hash, date, author, subject and refs. Of the current branch (or another), optionally only the commits that touched a path.", """{"limit":{"type":"integer","description":"At most this many commits (default 30, at most 200)."},"path":{"type":"string","description":"Only commits that changed this file or folder, relative to the workspace root."},"branch":{"type":"string","description":"A branch, tag or commit to start from; the current branch by default."}}"""),
        IdeTools.Read("git_file_history", "The commits that changed a file (following renames), or only some of its lines, newest first.", """{"path":{"type":"string","description":"A file, relative to the workspace root."},"startLine":{"type":"integer","description":"With endLine: only the commits that changed these lines (1-based)."},"endLine":{"type":"integer"},"limit":{"type":"integer","description":"At most this many commits (default 30, at most 200)."}}""", "path"),
        IdeTools.Read("git_blame", "Who last changed each line of a file, and in which commit (short hash, author, date, subject), with the lines' text.", """{"path":{"type":"string","description":"A file, relative to the workspace root."},"startLine":{"type":"integer","description":"The first line (1-based); the whole file by default."},"endLine":{"type":"integer","description":"The last line."}}""", "path"),
        IdeTools.Action("git_stage", "Stage files (git add) in Codalus IDE's Git Changes: the paths given (files or folders), or every change (all).", """{"paths":{"type":"array","items":{"type":"string"},"description":"Files or folders, relative to the workspace root."},"all":{"type":"boolean","description":"Every change, untracked files included."}}"""),
        IdeTools.Action("git_unstage", "Unstage files: their changes stay in the working tree. The paths given, or every staged change (all).", """{"paths":{"type":"array","items":{"type":"string"},"description":"Files or folders, relative to the workspace root."},"all":{"type":"boolean","description":"Every staged change."}}"""),
        IdeTools.Action("git_commit", "Commit the staged changes, or every change (all: stages them first, untracked files included), with the user's configured git identity. Never amends and never pushes.", """{"message":{"type":"string","description":"The commit message: a subject line, then a blank line and the body."},"all":{"type":"boolean","description":"Stage and commit every change, not only the staged ones."}}""", "message"),
        IdeTools.Action("git_stash", "The stashes: push the changes onto a new stash, pop one back into the working tree (it stays when it doesn't apply cleanly), or list them.", """{"action":{"type":"string","enum":["push","pop","list"],"description":"list by default."},"message":{"type":"string","description":"push: the stash's message."},"includeUntracked":{"type":"boolean","description":"push: untracked files too."},"index":{"type":"integer","description":"pop: which stash (0 is the newest, the default)."}}"""),
        IdeTools.Action("git_checkout", "Check out a branch: an existing local one, a remote one (origin/x: its local branch, made to track it when there is none), or a new one from the current commit (create). Changes in the working tree come along when they don't clash; git refuses otherwise.", """{"branch":{"type":"string","description":"The branch's name."},"create":{"type":"boolean","description":"Make a new branch with this name and check it out."}}""", "branch"),
        IdeTools.Read("git_conflicts", "The files in conflict during a merge, rebase, cherry-pick or revert, and the operation. With a path: that file's three versions (base, ours: the current branch, theirs: what comes in; during a rebase, ours is the branch being rebased onto).", """{"path":{"type":"string","description":"A conflicted file, relative to the workspace root: its versions."}}"""),
        IdeTools.Action("git_resolve", "Resolve a conflicted file and stage it: take ours or theirs whole, both (each conflict's ours then theirs), or content you give (the whole file, without conflict markers).", """{"path":{"type":"string","description":"A conflicted file, relative to the workspace root."},"take":{"type":"string","enum":["ours","theirs","both","content"]},"content":{"type":"string","description":"take content: the file's resolved text."}}""", "path", "take"),
    ];
}
